/**
 * Push command handler
 */
import { parsePushArgs, pushCommand } from "./command.js";
import { showHeader } from "../../utils/index.js";
import { parseArgsOrThrow } from "../../shared/args.js";
export async function handlePushCommand(args) {
    showHeader();
    await pushCommand(parseArgsOrThrow(parsePushArgs, "push", args));
}
